"Abstand Anfang / Ende":"Avstand start / slutt",
"Abstand Anfang / Ende macht aus der Lasche eine Teillasche. Weitere geschlossene Profile in der Skizze werden zu Ausschnitten in der Platte. Bohrungen und Fenster in einer Lasche: Mitte entlang der Kante (bei einer gebogenen Kante entlang des Bogens), Mitte ab Ende der Biegung, Größe – sie erscheinen auch in der Abwicklung. Geht eine gebogene Kante ohne Knick in ihre Nachbarkante über und haben beide eine Lasche mit gleichem Biegewinkel, laufen die Laschen ohne Freischnitt ineinander über. „Kontur aus Skizze“ schneidet die geschlossenen Profile einer Skizze aus der Lasche: ihr X läuft entlang der Kante, ihr Y in die Lasche hinein, der Nullpunkt liegt am Kantenanfang auf dem Ende der Biegung (verschiebbar).":"Avstand start / slutt gjør flensen til en delflens. Flere lukkede profiler i skissen blir til utsparinger i platen. Hull og vinduer i en flens: midte langs kanten (ved en buet kant langs buen), midte fra bøyens slutt, størrelse – de vises også i utfoldingen. Går en buet kant uten knekk over i nabokanten, og begge har en flens med samme bøyevinkel, løper flensene inn i hverandre uten frisnitt. «Kontur fra skisse» skjærer de lukkede profilene i en skisse ut av flensen: dens X går langs kanten, dens Y inn i flensen, nullpunktet ligger ved kantens start på bøyens slutt (kan flyttes).",
