"Alle Flächen des Merkmals wählen: bei einer Bohrung die Wand (und Senkung, Boden), bei einer Tasche Wände und Boden, bei einem Zapfen Mantel und Stirnfläche. Das Merkmal wandert um X/Y/Z; die alte Stelle wird geschlossen. Geht auch bei importierten STEP-Teilen ohne Verlauf. Beim ersten Mal lädt der große Geometriekern (einige Sekunden).":"Velg alle flater i elementet: for et hull veggen (og forsenkning, bunn), for en lomme vegger og bunn, for en tapp mantel og endeflate. Elementet flyttes med X/Y/Z; det gamle stedet lukkes. Fungerer også på importerte STEP-deler uten historikk. Første gang lastes den store geometrikjernen (noen sekunder).",
"Alle Flächen wählen, die verschwinden sollen (bei einer Tasche Wände und Boden, bei einer Bohrung die Wand, bei einer Verrundung die Rundung). Die Nachbarflächen werden über die Lücke verlängert. Der Schritt rechnet bei Änderungen am Körper mit; beim ersten Mal lädt dafür der große Geometriekern (einige Sekunden).":"Velg alle flater som skal forsvinne (for en lomme vegger og bunn, for et hull veggen, for en avrunding selve avrundingen). Naboflatene forlenges over hullet. Trinnet beregnes på nytt når kroppen endres; første gang lastes den store geometrikjernen (noen sekunder).",
