"Dateiname beim Export":"Filnavn ved eksport",
"Daten und Speicher":"Data og lagring",
"Datenpanel":"Datapanel",
"Datenpanel ein-/ausblenden":"Vis/skjul datapanel",
"Datenpanel öffnen…":"Åpne datapanel…",
"Datum":"Dato",
"Datum/Uhrzeit":"Dato/klokkeslett",
"Dauer etwa":"Varighet ca.",
"Deaktivieren":"Deaktiver",
"Deckfläche ersetzen":"Erstatt toppflate",
"Deckkraft":"Dekkevne",
"Deckkraft der Fenster":"Vinduenes dekkevne",
"Den Parameter benutzen: einen Schritt der Zeitleiste öffnen (Doppelklick, z. B. die Extrusion) und als Abstand =dicke eintippen.":"Bruk parameteren: åpne et trinn i tidslinjen (dobbeltklikk, f.eks. ekstruderingen) og skriv =dicke som avstand.",
"Den Schlüssel wie ein Kennwort behandeln: Wer ihn hat und auf diesem Rechner läuft, kann den geöffneten Entwurf ändern. Der Anschluss bleibt nur offen, solange WerkFab läuft.":"Behandle nøkkelen som et passord: Den som har den og kjører på denne datamaskinen, kan endre det åpne utkastet. Porten forblir bare åpen så lenge WerkFab kjører.",
"Den Wert ändern (z. B. 20) und eine zweite Variante speichern – in der Konfigurationstabelle lassen sich beide umschalten und als Teilefamilie exportieren.":"Endre verdien (f.eks. 20) og lagre en andre variant – i konfigurasjonstabellen kan du veksle mellom begge og eksportere dem som delfamilie.",
"Der Ablauf hat noch keine Dauer – Schritte mit Dauer anlegen.":"Forløpet har ingen varighet ennå – opprett trinn med varighet.",
"Der Anschluss antwortet nicht.":"Porten svarer ikke.",
"Der Durchmesser ist kleiner als die doppelte Wanddicke":"Diameteren er mindre enn dobbel veggtykkelse",
"Der Durchmesser würde null oder negativ – Abstand verkleinern":"Diameteren ville bli null eller negativ – reduser avstanden",
"Der Geometriekern konnte dieses Feature nicht berechnen – Maße und gewählte Kanten oder Flächen prüfen.":"Geometrikjernen kunne ikke beregne denne funksjonen – kontroller målene og de valgte kantene eller flatene.",
"Der Gewindefräser läuft im vollen Material: Den Zapfen vorher freifräsen (2D-Kontur außen um den Zapfen bis zur Gewindetiefe).":"Gjengefresen går i fullt materiale: frese fri tappen først (2D-kontur utenpå tappen ned til gjengedybden).",
"Der Körper hat auf dieser Ebene keinen Umriss.":"Kroppen har ikke noe omriss på dette planet.",
"Der Körper hat keine ebene Fläche":"Kroppen har ingen plan flate",
"Der Körper ist zu dick für ein Blech":"Kroppen er for tykk for en plate",
"Der Körper muss überall gleich dick sein – gezeichnet, extrudiert oder aus einer STEP-Datei. Erkannt werden die Blechdicke (Abstand der größten Fläche zu ihrer Gegenfläche), die ebenen Wände und die Biegungen dazwischen mit Winkel und Innenradius, rund oder scharfkantig. Daraus entsteht die Abwicklung; als Blech liegt sie als Skizze mit Biegelinien vor und lässt sich wie jedes Blech ändern, abwickeln und schachteln. Der K-Faktor bestimmt die gestreckten Längen. Zeigt die größte Fläche nach oben oder unten, liegt das Blech genau im Körper, sonst flach auf der XY-Ebene. Säume (180°) und gerundete Wände zwischen zwei ebenen Wänden werden als Biegung mit eigenem Radius übernommen. Nicht erkannt werden frei endende gerollte Ränder, Rohre und Umformungen wie Sicken.":"Kroppen må ha samme tykkelse overalt – tegnet, ekstrudert eller fra en STEP-fil. Gjenkjent blir platetykkelsen (avstanden fra den største flaten til motflaten), de plane veggene og bøyene mellom dem med vinkel og innvendig radius, runde eller skarpkantede. Av dette oppstår utbrettet; som plate foreligger det som en skisse med bøyelinjer og kan endres, brettes ut og nestes som enhver plate. K-faktoren bestemmer de strukkede lengdene. Peker den største flaten opp eller ned, ligger platen nøyaktig i kroppen, ellers flatt på XY-planet. Falser (180°) og avrundede vegger mellom to plane vegger overtas som en bøy med egen radius. Ikke gjenkjent blir fritt endende rullede kanter, rør og formgivinger som sikker.",
"Der Körper wird mit den Dreiecken der Anzeige als Netz übernommen. Er selbst bleibt erhalten; spätere Änderungen am Körper ändern das Netz nicht.":"Kroppen overtas som nett med visningens trekanter. Selve kroppen beholdes; senere endringer i kroppen endrer ikke nettet.",
"Der Körper wird um seine senkrechte Mittelachse abgetastet und als Halterkontur (Abschnitte) in der Dokument-Werkzeugbibliothek gespeichert.":"Kroppen avsøkes rundt sin vertikale midtakse og lagres som holderkontur (seksjoner) i dokumentets verktøybibliotek.",
"Der Link enthält kein Design.":"Lenken inneholder ikke noe design.",
"Der Link ist unvollständig oder beschädigt (beim Kopieren abgeschnitten?).":"Lenken er ufullstendig eller skadet (avkortet ved kopiering?).",
"Der Nahtspalt ist größer als der Umfang":"Sømspalten er større enn omkretsen",
"Der Punkt, um den sich die Ansicht dreht (bei freiem Orbit). „Unter dem Mauszeiger“: die Stelle des Modells, an der die Drehung beginnt.":"Punktet visningen roterer rundt (ved fri orbit). «Under musepekeren»: stedet på modellen der rotasjonen starter.",
"Der Radius wächst gleichmäßig vom Anfang zum Ende jeder gewählten Kante. Welches Ende der Anfang ist, legt die Kante fest – bei Bedarf tauschen.":"Radiusen øker jevnt fra start til slutt på hver valgte kant. Hvilken ende som er starten, bestemmes av kanten – bytt ved behov.",
"Der Rand einer Fläche ist eine geschlossene Kette: Mit „durchlaufend“ läuft der Radius einmal ringsum, ohne diese Option auf jeder Kante für sich vom Anfangs- zum Endradius.":"Kanten av en flate er en lukket kjede: med «gjennomgående» løper radiusen én gang hele veien rundt; uten dette alternativet løper den på hver kant for seg fra startradius til sluttradius.",
"Der Schnitt trifft keinen Körper – es wird kein Material entfernt.":"Snittet treffer ingen kropp – det fjernes ikke noe materiale.",
"Der Text steht als Kommentar an dieser Stelle im Programm.":"Teksten står som kommentar på dette stedet i programmet.",
"Der alte Schlüssel gilt dann nicht mehr; verbundene Agenten müssen neu eingerichtet werden":"Den gamle nøkkelen gjelder da ikke lenger; tilkoblede agenter må settes opp på nytt",
"Der erste Abstand wird auf der Fläche gemessen, die mehr nach oben (Z) zeigt, der zweite Abstand bzw. der Winkel gilt zur anderen Fläche. „Seiten tauschen“ kehrt das um. Tangential anschließende Kanten laufen mit.":"Den første avstanden måles på flaten som peker mest oppover (Z); den andre avstanden eller vinkelen gjelder mot den andre flaten. «Bytt sider» snur dette. Tangentielt tilstøtende kanter følger med.",
"Der gewählte Körper ist das Rohteil (z. B. ein Guss- oder Schmiederohling). Er wird selbst nicht bearbeitet.":"Den valgte kroppen er råemnet (f.eks. et støpe- eller smiemne). Den bearbeides ikke selv.",
"Der große Geometriekern ist noch nicht geladen":"Den store geometrikjernen er ikke lastet ennå",
