"Drehmaschine mit Y-Achse: Schlüsselflächen, Konturen und Taschen auf der Planfläche fahren mit feststehendem Teil (C fest) in X und Y – genauer als die Polar-Interpolation. Was über den Y-Weg hinausgeht, bleibt bei der Polar-Interpolation.":"Dreiebenk med Y-akse: nøkkelflater, konturer og lommer på planflaten kjøres med stillestående emne (C låst) i X og Y – mer nøyaktig enn polarinterpolasjon. Det som går utover Y-veien, blir værende på polarinterpolasjon.",
