"Durchzug {0}: Vorbohrung Ø {1} mm wird auf Ø {2} mm aufgeweitet (Faktor {3}).":"Krave {0}: forboring Ø {1} mm utvides til Ø {2} mm (faktor {3}).",
"Durchzug {0}: liegt {1} mm neben dem Rand (weniger als 2 × Blechdicke) – der Rand beult aus.":"Krave {0}: ligger {1} mm fra kanten (mindre enn 2 × platetykkelse) – kanten buler ut.",
"Durchzug {0}: zu hoch für diese Bohrung (die Vorbohrung bliebe ohne Durchmesser)":"Krave {0}: for høy for dette hullet (forboringen ville bli uten diameter)",
"Durchzug: der Rand einer runden Bohrung wird zu einem Kragen hochgezogen, etwa als Gewindedurchzug. Der Bohrungsdurchmesser der Skizze ist der fertige Innendurchmesser; im Zuschnitt wird die kleinere Vorbohrung geschnitten.":"Krave: kanten av et rundt hull trekkes opp til en krave, for eksempel som gjengekrave. Hulldiameteren i skissen er ferdig innvendig diameter; i emnet skjæres den mindre forboringen.",
