"Eilgangweg":"Ilgangvei",
"Ein Gelenk anlegen: ZUSAMMENBAU → „Gelenk“ (J), erst das bewegliche Teil, dann das feste anklicken, Art „Drehgelenk“ oder „Schiebegelenk“.":"Opprett et ledd: SAMMENSTILLING → «Ledd» (J), klikk først på den bevegelige delen, så på den faste, type «Dreieledd» eller «Glideledd».",
"Ein Rechteck zeichnen: Werkzeug „Rechteck“ (R), zwei Ecken anklicken. Maße kann man direkt eintippen, z. B. 80 und 50.":"Tegn et rektangel: verktøyet «Rektangel» (R), klikk på to hjørner. Mål kan skrives inn direkte, f.eks. 80 og 50.",
"Ein Rechtsklick in einen Dialog (nicht in ein Eingabefeld) drückt dessen OK-Schaltfläche":"Et høyreklikk i en dialog (ikke i et inndatafelt) trykker på OK-knappen",
"Ein anderes gespeichertes Design als Komponente einfügen":"Sett inn et annet lagret design som komponent",
"Ein eingefügter Satz verschiebt alle folgenden Satznummern – so zählen sie nicht als Änderung":"En innsatt blokk forskyver alle etterfølgende blokknumre – slik teller de ikke som endring",
"Ein gerollter Rand über 350° schließt sich zum Rohr – das ist so nicht herstellbar":"En rullet kant over 350° lukker seg til et rør – det kan ikke produseres slik",
"Ein geschlossenes Netz in einen Volumenkörper umwandeln (jedes Dreieck wird eine Fläche)":"Konverter et lukket nett til en volumkropp (hver trekant blir en flate)",
"Ein runder Fräser lässt in jeder Innenecke seinen Radius stehen – ein eckiges Gegenstück passt dann nicht hinein. Der Freistich fährt an jeder scharfen Innenecke kurz in die Ecke und zurück.{0}{1}":"En rund fres lar radiusen sin stå igjen i hvert innvendige hjørne – en kantet motdel passer da ikke inn. Avlastningen kjører kort inn i hjørnet og tilbake ved hvert skarpe innvendige hjørne.{0}{1}",
"Ein verbundener Agent arbeitet am geöffneten Entwurf: Er liest und ändert die Zeitachse, fragt Körper, Volumen und Fehler ab, holt Normteile aus dem Bauteilkatalog, lässt sich ein Bild der Ansicht geben, exportiert STEP oder STL, legt Werkzeuge und Fertigungsoperationen an und gibt das NC-Programm aus – das vor dem ersten Schnitt zu prüfen bleibt. Auf Dateien, Einstellungen und andere Entwürfe hat er keinen Zugriff. Jede Änderung ist ein Schritt, den Strg+Z zurücknimmt.":"En tilkoblet agent arbeider på det åpne utkastet: Den leser og endrer tidslinjen, spør etter kropper, volum og feil, henter standarddeler fra delkatalogen, får et bilde av visningen, eksporterer STEP eller STL, oppretter verktøy og produksjonsoperasjoner og skriver ut NC-programmet – som fortsatt må kontrolleres før det første snittet. Den har ikke tilgang til filer, innstillinger eller andre utkast. Hver endring er ett trinn som Ctrl+Z angrer.",
"Ein zweiter Klick auf die Schaltfläche des Zeichenwerkzeugs schaltet zurück auf Auswählen":"Et nytt klikk på knappen til tegneverktøyet bytter tilbake til Velg",
