"Eine Bearbeitung anlegen, z. B. FRÄSEN → „2D-Kontur“ oder „Planfräsen“, Werkzeug wählen, OK.":"Opprett en operasjon, f.eks. FRESING → «2D-kontur» eller «Planfresing», velg verktøy, OK.",
"Eine Bohrung setzen: „Bohrung“ (H), auf die Oberseite klicken, Durchmesser wählen, OK. (Eine Extrusion mit „Ausschneiden“ zählt auch.)":"Plasser et hull: «Hull» (H), klikk på oversiden, velg diameter, OK. (En ekstrudering med «Skjære ut» teller også.)",
"Eine Explosionsansicht braucht mindestens zwei Körper.":"En sprengskisse trenger minst to kropper.",
"Eine Explosionsansicht öffnen: „Explosionsansicht“ – „Montageanleitung“ macht daraus eine Seite mit Bildern.":"Åpne en sprengskisse: «Sprengskisse» – «Monteringsanvisning» lager en side med bilder av den.",
"Eine Fläche, Bohrung oder einen Zapfen anklicken.":"Klikk på en flate, et hull eller en tapp.",
"Eine Fläche, Bohrung oder einen Zapfen eines Körpers anklicken.":"Klikk på en flate, et hull eller en tapp på en kropp.",
"Eine Konfiguration merkt sich die Ausdrücke aller Parameter unter einem Namen – etwa „kurz“ und „lang“. Ein Klick stellt die Variante wieder her.":"En konfigurasjon husker uttrykkene til alle parametere under et navn – for eksempel «kort» og «lang». Ett klikk gjenoppretter varianten.",
"Eine Platte mit Bohrung und abgerundeten Kanten – Skizze, Extrusion, Bohrung und Verrundung.":"En plate med hull og avrundede kanter – skisse, ekstrudering, hull og avrunding.",
"Eine Seite":"Én side",
"Eine Seite mit einem Bild je Montageschritt (Explosion rückwärts), druckbar und als PDF":"En side med ett bilde per monteringstrinn (sprenging baklengs), utskrivbar og som PDF",
"Eine Variante speichern: VERWALTEN → „Konfigurieren“, Name z. B. dünn.":"Lagre en variant: ADMINISTRER → «Konfigurer», navn f.eks. tynn.",
