"Es braucht einen Körper – falls noch keiner da ist, zuerst die Aufgabe „Erstes Teil“ machen.":"Det trengs en kropp – finnes det ingen ennå, gjør først leksjonen «Første del».",
"Es braucht mindestens zwei Körper (z. B. zwei Extrusionen mit „Neuer Körper“).":"Det trengs minst to kropper (f.eks. to ekstruderinger med «Ny kropp»).",
