"Fläche am bewegten Körper gewählt":"flate på den flyttede kroppen valgt",
"Fläche anklicken – die Bohrung entsteht mit":"Klikk på en flate – hullet opprettes samtidig",
"Fläche anklicken: an jedem Klickpunkt entsteht die Durchgangsbohrung für die Schraube (ISO 273, Reihe mittel) durch alle Teile, die dort aufeinanderliegen – für Senkschrauben mit 90°-Senkung, für Zylinderschrauben auf Wunsch mit Senkbohrung (DIN 974-1, Reihe 1) so tief wie der Kopf. Die Schraube sitzt gleich darin. Bohrung und Schraube lassen sich danach im Verlauf ändern.":"Klikk på en flate: i hvert klikkpunkt opprettes gjennomgangshullet for skruen (ISO 273, middels rekke) gjennom alle deler som ligger oppå hverandre der – for senkskruer med 90° forsenkning, for sylinderskruer etter ønske med sylindrisk forsenkning (DIN 974-1, rekke 1) like dyp som hodet. Skruen sitter straks i hullet. Hull og skrue kan deretter endres i tidslinjen.",
"Fläche eines Körpers anklicken: ihr Rand kommt als Kontur in die Skizze. Eine Kante anklicken projiziert nur diese Kante (Kreise bleiben Kreise). Projizierte Geometrie ist violett.":"Klikk på en flate på en kropp: kanten legges inn i skissen som kontur. Klikk på en kant projiserer bare denne kanten (sirkler forblir sirkler). Projisert geometri er fiolett.",
