"Flächen am Körper":"Flater på kroppen",
"Flächen am Teilende (Zweiflach, Vierkant, Sechskant) mit einem angetriebenen Schaftfräser entlang Z. Schlüsselweite = doppelter Abstand der Fläche von der Drehachse. X und C fahren gemeinsam (Polar-Interpolation, Fanuc G12.1); ohne diese Vorlage im Postprozessor werden kurze X/C-Schritte ausgegeben.":"Flater i enden av delen (toflate, firkant, sekskant) med en drevet sluttfres langs Z. Nøkkelvidde = dobbelt avstand fra flaten til dreieaksen. X og C beveger seg sammen (polar interpolasjon, Fanuc G12.1); uten denne malen i postprosessoren utgis korte X/C-trinn.",
"Flächen anklicken, die aufgedickt werden (erneut klicken entfernt).":"Klikk på flater som skal gis tykkelse (nytt klikk fjerner).",
"Flächen anklicken, die geneigt werden (erneut klicken entfernt).":"Klikk på flatene som skal gis helling (nytt klikk fjerner).",
