"Gemeinsame Schnittkanten nur einmal schneiden":"Skjær felles snittkanter bare én gang",
"Gemeinsame Schnittkanten: liegen zwei Zuschnitte genau eine Schnittfuge auseinander (beim Schachteln als Abstand die Schnittfuge eintragen), fällt ihre Bahn auf der gemeinsamen Kante zusammen und wird nur einmal geschnitten. Der Anschnitt liegt nie in einem Nachbarteil: ist neben einer Kontur kein freier Abfall, wird auf der Kontur eingestochen. Nach „Vorschau“ zeigt ein Bild je Tafel die Bahn, bevor die Dateien gespeichert werden.":"Felles snittkanter: ligger to emner nøyaktig én snittbredde fra hverandre (oppgi snittbredden som avstand ved nesting), faller banen deres sammen på den felles kanten og skjæres bare én gang. Innkjøringen ligger aldri i en nabodel: er det ikke fritt avfall ved siden av en kontur, stikkes det inn på konturen. Etter «Forhåndsvisning» viser et bilde per plate banen før filene lagres.",
