"Gerade Linien der Skizze, die zu keinem Profil gehören (auch Hilfslinien). Biegung: die Linie ist die Mitte der Biegezone, die Skizze dort der Zuschnitt – das größte Stück der Platte bleibt liegen, alles jenseits der Linie schwenkt mit seinen Laschen mit. Die Linie gilt über die ganze Platte. Sicke: eine Rippe entlang der Linie, im Querschnitt und an den Enden rund; das Blech behält seine Dicke.":"Rette linjer i skissen som ikke hører til noen profil (også hjelpelinjer). Bøy: linjen er midten av bøyesonen, og skissen er emnet der – det største stykket av platen blir liggende, alt på den andre siden av linjen svinger med flensene sine. Linjen gjelder over hele platen. Sikke: en rib langs linjen, rund i tverrsnitt og i endene; platen beholder tykkelsen sin.",
"Gerade Nuten (Langloch oder Linie mit Nutbreite) gehen als Nutzyklus der Steuerung heraus.":"Rette spor (langhull eller linje med sporbredde) sendes ut som styringens sporsyklus.",
