"Geschafft! Das Teil steht in der Zeitleiste unten – ein Doppelklick auf einen Schritt ändert ihn nachträglich. Weiter geht es mit „Maße als Parameter“ oder „Vom Teil zum NC-Programm“.":"Ferdig! Delen ligger i tidslinjen nederst – dobbeltklikk på et trinn for å endre det i ettertid. Fortsett med «Mål som parametere» eller «Fra del til NC-program».",
"Geschlossen":"Lukket",
"Geschlossen (Gehrung)":"Lukket (gjæring)",
"Geschlossen: Laschen an zwei Nachbarkanten laufen bis zur Winkelhalbierenden der Ecke und lassen dort den Spalt frei. Die Eckfreistellung sitzt, wo sich die Biegezonen kreuzen – in der Abwicklung und im gebogenen Teil. Auch eine Lasche an einer gebogenen Kante wird an einer echten Ecke auf Gehrung geschnitten (dort ohne Eckfreistellung).":"Lukket: flenser på to nabokanter går frem til hjørnets halveringslinje og lar spalten stå åpen der. Hjørneavlastningen sitter der bøyesonene krysser hverandre – i utbredelsen og i den bøyde delen. Også en flens på en buet kant skjæres på gjæring i et ekte hjørne (der uten hjørneavlastning).",
"Geschlossene Kette {0}":"Lukket kjede {0}",
"Geschlossene Profile begrenzen den Bereich.":"Lukkede profiler avgrenser området.",
"Geschlossene Profile der aktiven Skizze farbig füllen":"Fyll lukkede profiler i den aktive skissen med farge",
"Geschlossene Profile werden zu ebenen Flächen – z. B. Deckel und Boden, um Flächen anschließend zu einem Körper zusammenzufügen.":"Lukkede profiler blir til plane flater – f.eks. topp og bunn, for å sy flatene sammen til en kropp etterpå.",
