"Gewindebohrung im untersten Teil":"Gjengehull i den nederste delen",
"Gewindebohrung im untersten Teil: die Durchgangsbohrung endet, wo das unterste Teil beginnt; dort entsteht das Kernloch mit Gewinde – drei Gewindegänge tiefer, als die Schraube reicht, oder durch das ganze Teil. Liegt nur ein Teil unter dem Punkt, bekommt es das Gewinde von der Fläche an. „Länge passend zur Einschraubtiefe“ nimmt die nächste Länge der Reihe, mit der die Schraube etwa so tief im Gewinde sitzt, wie ihr Gewinde dick ist (Richtwert für Stahl) – aber nie länger, als das Teil dick ist.":"Gjengehull i den nederste delen: gjennomgangshullet slutter der den nederste delen begynner; der lages kjernehullet med gjenger – tre gjenger dypere enn skruen rekker, eller gjennom hele delen. Ligger bare én del under punktet, får den gjenger fra flaten. «Lengde tilpasset inngrepsdybden» velger neste lengde i rekken som gjør at skruen sitter omtrent like dypt i gjengen som gjengen er tykk (veiledende verdi for stål) – men aldri lengre enn delen er tykk.",
"Gewindebohrung {0} – Einschraubtiefe nur {1} mm":"gjengehull {0} – inngjengingsdybde bare {1} mm",
"Gewindebohrung {0}, Einschraubtiefe {1} mm":"gjengehull {0}, inngjengingsdybde {1} mm",
"Gewindebohrung: gebohrt wird das Kernloch; das Gewinde erscheint als Gewindedarstellung am Modell und mit seinem Namen in der Zeichnung.":"Gjengehull: kjernehullet bores; gjengen vises som gjengesymbol på modellen og med navnet i tegningen.",
