"Gleiche Durchmesser ergeben ein Rohr, verschiedene einen Kegelstumpf. Die Abwicklung wird auf der neutralen Faser gerechnet (Innenfläche + K-Faktor × Blechdicke); beim Runden liegt sie näher an der Blechmitte als beim Abkanten – üblich ist ein K-Faktor von 0,45 bis 0,5. Mit einer Blechregel gelten deren Dicke und K-Faktor. Der Nahtspalt bleibt am größeren Durchmesser offen (0 = stumpf gestoßen, im Körper dann ein Schlitz von 0,01 mm).":"Like diametre gir et rør, ulike gir en avkortet kjegle. Utbrettet beregnes på nøytral fiber (innerflate + K-faktor × platetykkelse); ved rulling ligger den nærmere platens midte enn ved kantpressing – vanlig K-faktor er 0,45 til 0,5. Med en plateregel gjelder dens tykkelse og K-faktor. Sømspalten blir stående åpen ved den største diameteren (0 = stumt støtt, i kroppen da en slisse på 0,01 mm).",
"Gleicher Abstand":"Lik avstand",
"Gleichlauf":"Medlø",
"Gleichmäßige Dreiecke dieser Größe: lange Kanten werden geteilt, danach wird auf die Dreieckszahl eines gleichmäßigen Netzes reduziert. Gut vor dem Glätten oder Formen von Scans.":"Jevne trekanter av denne størrelsen: lange kanter deles, deretter reduseres til trekantantallet i et jevnt nett. Bra før utjevning eller forming av skanninger.",
