"Halbzeug: Nennmaße der Norm, auf jede Länge zugeschnitten. Nicht jede Paarung von Maß und Wanddicke ist bei jedem Händler am Lager. Ein Rohr entlang einer Skizzenlinie – auch um Ecken und Bögen – legt der Befehl „Rohr“ an.":"Halvfabrikat: standardens nominelle mål, tilskåret til en hvilken som helst lengde. Ikke alle kombinasjoner av mål og veggtykkelse er på lager hos alle forhandlere. Et rør langs en skisselinje – også rundt hjørner og buer – opprettes med kommandoen «Rør».",
