"Heidenhain: an der Steuerung die Datenübertragung über Ethernet freigeben (wie für TNCremo, LSV2, Port 19000); Standardordner TNC 640 TNC:\\nc_prog\\, iTNC 530 TNC:\\. FTP: Port 21, Ordner z. B. /_N_WKS_DIR oder /NC. Netzwerkordner: Pfad wie \\\\MASCHINE\\NC oder Z:\\NC. DNC: Wandler als TCP-Server (raw), meist Port 4001; an der Steuerung „Abarbeiten extern“, DNC oder TAPE starten.":"Heidenhain: frigi dataoverføring via Ethernet på styringen (som for TNCremo, LSV2, port 19000); standardmappe TNC 640 TNC:\\nc_prog\\, iTNC 530 TNC:\\. FTP: port 21, mappe f.eks. /_N_WKS_DIR eller /NC. Nettverksmappe: sti som \\\\MASCHINE\\NC eller Z:\\NC. DNC: omformer som TCP-server (raw), oftest port 4001; start „Kjøre eksternt“, DNC eller TAPE på styringen.",
