"Importierte Körper sind ohne Konstruktionshistorie, lassen sich aber weiterbearbeiten (Verrundung, Fase, Ausschneiden …) und für CAM verwenden. Mit „Y-Achse oben“ werden Modelle aus Programmen mit Y nach oben richtig hingestellt.":"Importerte kropper har ingen konstruksjonshistorikk, men kan redigeres videre (avrunding, fas, utskjæring …) og brukes til CAM. Med «Y-akse opp» settes modeller fra programmer med Y oppover riktig.",
