"Je Operation zwei Q-Parameter am Programmanfang: der erste verschiebt die Tiefe (DL, + = weniger tief), der zweite das seitliche Aufmaß (DR, + = mehr Aufmaß; wirkt nur bei Radiuskorrektur an der Steuerung RL/RR). An der Maschine eine Zahl ändern statt Sätze suchen.":"To Q-parametere per operasjon i starten av programmet: den første forskyver dybden (DL, + = mindre dypt), den andre sideovermålet (DR, + = mer overmål; virker bare med radiuskorreksjon i styringen RL/RR). Endre ett tall i maskinen i stedet for å lete etter blokker.",
"Je Skizze die erste Kurve – offen oder geschlossen. Die Kurven werden mit einer Haut verbunden (Fläche ohne Dicke).":"Første kurve i hver skisse – åpen eller lukket. Kurvene forbindes med et skall (flate uten tykkelse).",
"Je Tafel eine Datei. Die Bahn läuft um die halbe Schnittfuge (beim Fräsen den halben Fräser) neben dem Umriss im Abfall; Ausschnitte kommen vor dem Umriss ihres Teils, jede Kontur beginnt mit einem Anschnitt aus dem Abfall. Kiemenschlitze werden auf ihrer Linie geschnitten. Haltestege: so viele Stellen je Umriss bleiben stehen (Laser, Plasma, Wasserstrahl: der Strahl setzt dort aus; Fräsen: der Fräser hebt auf halbe Blechdicke), Umrisse unter 40 mm Länge bekommen keine. „Steuerung“ legt fest, womit der Strahl ein- und ausgeschaltet wird; die Einstechzeit steht als G4 im Programm, außer die Steuerung sticht selbst ein. Nullpunkt ist die linke untere Ecke der Tafel, beim Fräsen Z0 die Blechoberseite. Das Programm vor dem Einsatz an der Maschine oder in einem NC-Simulator prüfen.":"Én fil per plate. Banen går i avfallet ved siden av konturen, med en avstand på halv snittbredde (ved fresing halve fresen); utsnitt kommer før konturen til delen sin, og hver kontur begynner med en innkjøring fra avfallet. Louvere skjæres langs sin linje. Holdebroer: så mange steder per kontur blir stående (laser, plasma, vannstråle: strålen slår seg av der; fresing: fresen løftes til halv platetykkelse); konturer kortere enn 40 mm får ingen. «Styring» bestemmer hvordan strålen slås på og av; gjennomstikktiden står som G4 i programmet, med mindre styringen stikker gjennom selv. Nullpunktet er nederste venstre hjørne av platen, ved fresing er Z0 platens overside. Kontroller programmet på maskinen eller i en NC-simulator før bruk.",
"Je Werkzeug alle Teile (weniger Werkzeugwechsel)":"Alle deler per verktøy (færre verktøyskift)",
"Jede Achse einzeln: Kante, Ecke, Fläche oder Bohrung anklicken. Nicht gesetzte Achsen kommen vom Rohteilpunkt.":"Hver akse for seg: klikk på en kant, et hjørne, en flate eller et hull. Akser som ikke er satt hentes fra råemnepunktet.",
"Jede Bohrung wird mit ihren Koordinaten einzeln angefahren (X/Y je Bohrung) – kein Lochkreis- oder Rastermuster.":"Hvert hull kjøres til enkeltvis med sine koordinater (X/Y per hull) – ingen hullsirkel- eller rutenettmønster.",
"Jede Operation als Unterprogramm (LBL) am Programmende, Aufruf mit CALL LBL":"Hver operasjon som underprogram (LBL) på slutten av programmet, kalles med CALL LBL",
"Jede Variante berechnen und als STEP, STL oder 3MF speichern (eine ZIP-Datei)":"Beregn hver variant og lagre som STEP, STL eller 3MF (én ZIP-fil)",
"Jeder Kreis der Skizze ist ein Bohrungsmittelpunkt. Gebohrt wird entgegen der Skizzennormalen (ins Material).":"Hver sirkel i skissen er et hullsenter. Det bores mot skissenormalen (inn i materialet).",
"Jeder Kreis der Skizze wird um die Mitte (in Skizzenkoordinaten) gedreht wiederholt – ein Kreis im Abstand des Teilkreisradius ergibt einen Lochkreis.":"Hver sirkel i skissen gjentas rotert rundt midtpunktet (i skisskoordinater) – en sirkel i avstand lik delesirkelradiusen gir en hullsirkel.",
"Jeder Kreis der Skizze wird zum Raster: Abstände in X und Y der Skizze (auch negativ).":"Hver sirkel i skissen blir et rutenett: avstander i X og Y i skissen (også negative).",
"Jeder sichtbare Körper wird ein Glied mit Netz (STL, in Metern), Masse und Trägheit, jedes Gelenk ein Gelenk mit Achse und Grenzen. Die jetzige Stellung ist die Nullstellung. Mit einem Paketnamen stehen die Netze im URDF als package://Name/meshes/…, sonst als relativer Pfad.":"Hver synlige kropp blir en lenke med nett (STL, i meter), masse og treghet, hvert ledd et ledd med akse og grenser. Gjeldende stilling er nullstillingen. Med et pakkenavn står nettene i URDF som package://Name/meshes/…, ellers som relativ sti.",
"Jedes # im Skizzentext wird durch die Nummer ersetzt, mit Nullen aufgefüllt (SN-#### → SN-{0}). Bei mehreren Teilen in einer Aufspannung bekommt jedes Teil die nächste Nummer: {1}{2}.":"Hver # i skisseteksten erstattes med nummeret, fylt opp med nuller (SN-#### → SN-{0}). Med flere deler i én oppspenning får hver del neste nummer: {1}{2}.",
"Jedes Teil hat seinen eigenen Nullpunkt in der Steuerung (G54, G55 … bzw. Bezugspunkt-Nummer in der Tabelle – Heidenhain Zyklus 247). Alle Nullpunkte vorher an der Maschine setzen.":"Hver del har sitt eget nullpunkt i styringen (G54, G55 … eller referansepunktnummer i tabellen – Heidenhain syklus 247). Sett alle nullpunkter i maskinen på forhånd.",
"Jedes eigene Maß und jeder Toleranzrahmen bekommt eine Nummer in einem Kreis. Die Liste enthält Nennmaß, Toleranz, Höchst- und Mindestmaß und Felder für den Istwert. Maße ohne eigene Toleranz bekommen die Allgemeintoleranz.":"Hvert eget mål og hver toleranseramme får et nummer i en sirkel. Listen inneholder nominelt mål, toleranse, største og minste mål og felt for faktisk verdi. Mål uten egen toleranse får den generelle toleransen.",
"Jetzigen Stand festhalten":"Lagre nåværende tilstand",
"Jetzt einen Punkt auf dem zweiten Schenkel.":"Nå et punkt på det andre benet.",
