"Kappe schieben = verschieben, drücken/ziehen = zoomen, kippen und drehen = Modell drehen. In Skizzen nur Verschieben und Zoomen. SpaceMouse Pro/Enterprise: T, F, R = Ansicht oben, vorne, rechts. Falls nichts passiert: 3Dconnexion-Treiber kurz beenden und neu verbinden.":"Skyv hetten = panorere, trykk/dra = zoome, vipp og vri = rotere modellen. I skisser kun panorering og zooming. SpaceMouse Pro/Enterprise: T, F, R = visning ovenfra, forfra, fra høyre. Hvis ingenting skjer: avslutt 3Dconnexion-driveren kort og koble til på nytt.",
