"Kugel-, Schaft-, Torus- oder Konusfräser. Ein Kugelfräser behält seine Bahn; andere Fräser werden geneigt und entlang ihrer Achse verschoben, bis sie am Teil anliegen, ohne es zu verletzen. Höchstens die größte Neigung; wo Schaft oder Halter das Teil berühren würden, richtet sich das Werkzeug auf. Ausgabe als Werkzeugvektor (Heidenhain, Sinumerik, Fanuc), sonst als 3-Achs-Bahn.":"Kule-, ende-, torus- eller konisk fres. En kulefres beholder banen sin; andre fresere vippes og forskyves langs aksen til de ligger mot delen uten å skade den. Maksimalt den største helningen; der hvor skaftet eller holderen ville berøre delen, retter verktøyet seg opp igjen. Utdata som verktøyvektor (Heidenhain, Sinumerik, Fanuc), ellers som 3-akset bane.",
