"Lasche an Lasche: Winkel + biegt in dieselbe Richtung weiter (U-Profil, Falz mit 180°), − in die Gegenrichtung (Z-Stufe, Hutprofil). Saum: der Rand der Lasche wird um 180° auf sich selbst zurückgelegt – offen mit einem Spalt von einer Blechdicke, geschlossen flach zugedrückt; mit − 180° liegt er auf der anderen Seite. Das Feld R ist der Innenradius nur dieser Biegung (leer = wie beim Blech). Für einen Saum direkt an der Plattenkante die Lasche selbst auf 180° stellen. Kröpfung: zwei Biegungen gegeneinander (− 45° und + 45°) – der Rand läuft parallel versetzt weiter; Versatz über die Länge des schrägen Stücks und die Winkel.":"Flens på flens: vinkel + bøyer videre i samme retning (U-profil, omfals med 180°), − i motsatt retning (Z-trinn, hatteprofil). Fals: kanten av flensen legges 180° tilbake over seg selv – åpen med en spalte på én platetykkelse, lukket presset flatt; med − 180° ligger den på andre siden. Feltet R er innvendig radius bare for denne bøyen (tom = som for platen). For en fals rett på platekanten settes selve flensen til 180°. Forsetting: to bøyer mot hverandre (− 45° og + 45°) – kanten fortsetter parallelt forskjøvet; forskyvningen følger av lengden på det skrå stykket og vinklene.",
"Lasche {0}":"Flens {0}",
