"Macht ein geschlossenes Netz hohl: eine Innenwand im Abstand der Wandstärke kommt dazu – spart Material und Druckzeit. Stellen, die dünner sind als zwei Wandstärken, überschneiden sich danach; für Harzdruck ein Ablaufloch mit „Boolesch“ abziehen.":"Gjør et lukket nett hult: en innervegg i avstand lik veggtykkelsen legges til – sparer materiale og printetid. Steder som er tynnere enn to veggtykkelser, overlapper etterpå; for harpiksprinting trekkes et avløpshull fra med «Boolsk».",
