"Mehrere aneinanderhängende Kanten zählen als eine Strecke: Der Radius läuft vom Anfang der Kette bis zu ihrem Ende, Stützpunkte gelten in % der ganzen Kettenlänge. Das rechnet der große Geometriekern.":"Flere sammenhengende kanter regnes som én strekning: radiusen løper fra starten av kjeden til slutten, støttepunkter angis i % av hele kjedelengden. Dette beregnes av den store geometrikjernen.",
"Mehrfachaufspannung":"Flere deler",
