"Mehrfachaufspannung: Nullpunktverschiebung gibt es in diesem Postprozessor nicht – „Eigener Nullpunkt je Teil“ wählen; nur ein Teil ausgegeben":"Flere deler: denne postprosessoren har ikke nullpunktforskyvning – velg «Eget nullpunkt per del»; bare én del sendt ut",
"Meine Designs · {0}":"Mine design · {0}",
"Meine Werkzeuge":"Mine verktøy",
"Meldet Bahnen, die tiefer schneiden als das Modell an dieser Stelle (Schaft-, Plan-, Kugel- und Torusfräser, Fasenfräser und Bohrer mit ihrem Kegel; 3-Achs-Bewegungen). Ein Schnitt, der nicht im Modell steht – Gravur, Eckenfreistich, Tasche nur aus einer Skizze – wird ebenfalls gemeldet.":"Melder baner som skjærer dypere enn modellen på det stedet (skaft-, plan-, kule- og torusfreser, fasefreser og bor med kjeglen sin; 3-akse-bevegelser). Et kutt som ikke finnes i modellen – gravering, hjørnefrigang, lomme bare fra en skisse – meldes også.",
"Meldung auf dem Bildschirm der Steuerung: Fanuc und LinuxCNC als (MSG, …), Sinumerik als MSG(\"…\"), sonst als Kommentar.":"Melding på styringens skjerm: Fanuc og LinuxCNC som (MSG, …), Sinumerik som MSG(\"…\"), ellers som kommentar.",
