"Mit Stützpunkten läuft der Radius durch die angegebenen Werte (Lage in % der Kantenlänge). Das rechnet der große Geometriekern; beim ersten Mal lädt er einige Sekunden.":"Med støttepunkter løper radiusen gjennom de angitte verdiene (posisjon i % av kantlengden). Dette beregnes av den store geometrikjernen; første gang tar innlastingen noen sekunder.",
"Mit dem 3D-Taster kann nicht zerspant werden":"3D-føleren kan ikke brukes til skjæring",
"Mit dem Fertigteil vergleichen: grün = auf Maß, blau = Restmaterial, rot = zu tief":"Sammenlign med ferdigdelen: grønn = på mål, blå = restmateriale, rød = for dypt",
"Mit dem Reiter „{0}“ vergleichen?\n\nAbbrechen = eine Datei wählen":"Sammenligne med fanen «{0}»?\n\nAvbryt = velg en fil",
"Mit dem Werkzeug-Taster (TT) direkt nach dem TOOL CALL: Q340=1 prüft gegen die Werkzeugtabelle, schreibt die Abweichung als DL/DR und sperrt das Werkzeug bei überschrittener Verschleiß- oder Bruchtoleranz":"Med verktøytasteren (TT) rett etter TOOL CALL: Q340=1 kontrollerer mot verktøytabellen, skriver avviket som DL/DR og sperrer verktøyet når slitasje- eller bruddtoleransen er overskredet",
"Mit der Maus neben eine Kontur fahren (die Seite bestimmt die Richtung) · Esc beendet":"Beveg musen ved siden av en kontur (siden bestemmer retningen) · Esc avslutter",
"Mit diesem Werkzeug kann nicht gefräst werden":"Dette verktøyet kan ikke brukes til fresing",
"Mit einem Gewindebohrer nur Zyklus „Gewindebohren“ – ein Bohrzyklus würde ihn abbrechen":"Med en gjengetapp bare syklusen «Gjengetapping» – en borsyklus ville knekt den",
"Mit mehreren Zustellungen wird die Gewindetiefe in Schritten gefräst, die jeweils etwa gleich viel abnehmen – schont kleine Gewindefräser und harte Werkstoffe. Der Leerdurchgang fährt die letzte Bahn noch einmal ohne Zustellung.":"Med flere tilsettinger freses gjengedybden i trinn som hver fjerner omtrent like mye – skånsomt for små gjengefresere og harde materialer. Det tomme passet kjører siste bane én gang til uten tilsetting.",
"Mit „Bohrzyklen“ im NC-Programm werden Steuerungszyklen ausgegeben (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), sonst ausgeschriebene Bewegungen.":"Med «Borsykluser» i NC-programmet utgis styringssykluser (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), ellers utskrevne bevegelser.",
"Mit „Original behalten“ werden Original und Spiegelbild ein Netz; Punkte auf der Spiegelebene werden verbunden – aus einer offenen Hälfte wird so ein geschlossenes Teil.":"Med «Behold original» blir original og speilbilde ett nett; punkter på speilplanet forbindes – en åpen halvdel blir dermed en lukket del.",
