"Nur das Ende eines Linienzugs lässt sich stutzen oder verlängern.":"Bare enden av en polylinje kan trimmes eller forlenges.",
"Nur das bearbeiten, was ein größerer Fräser in Ecken stehen gelassen hat.":"Bearbeid kun det en større fres har latt stå igjen i hjørner.",
"Nur die Registerkarten zeigen":"Vis bare fanene",
"Nur die Stellen der Kontur nachfahren, die ein größerer Fräser nicht erreicht hat (Innenecken, enge Stellen). Ohne An-/Abfahrbögen, Haltestege und Schlichtdurchgänge; Korrektur im Rechner.":"Følg kun de delene av konturen som en større fres ikke nådde (innvendige hjørner, trange steder). Uten inn-/utkjøringsbuer, holdestegger og finbearbeidingspass; kompensasjon i datamaskinen.",
"Nur dort, wo das Referenzwerkzeug nicht hinkam: flache Bereiche parallel, steile Bereiche als Wasserlinie. Mit einem Werkzeug aus der Liste zählt dessen Form mit – zum Beispiel was ein Torusfräser in den Hohlkehlen stehen lässt.":"Bare der referanseverktøyet ikke kom til: flate områder parallelt, bratte områder som vannlinje. Med et verktøy fra listen teller formen med – for eksempel det en torusfres lar stå igjen i hulkilene.",
"Nur ebene Flächen können als Skizzenebene dienen.":"Bare plane flater kan brukes som skisseplan.",
