"Nur ebene Flächen, die nach oben zum Werkzeug zeigen (waagerecht in diesem Setup).":"Bare plane flater som peker opp mot verktøyet (vannrette i denne oppspenningen).",
"Nur für Außen-Drehmeißel":"Bare for utvendige dreiestål",
