"Offene oder geschlossene Kurven werden senkrecht zur Skizze gezogen – es entsteht eine Fläche (Wand ohne Dicke). Mit „Aufdicken“ oder „Zusammenfügen“ wird daraus ein Volumen.":"Åpne eller lukkede kurver trekkes vinkelrett på skissen – resultatet er en flate (vegg uten tykkelse). Med «Gi tykkelse» eller «Sy sammen» blir den til et volum.",
"Offene oder geschlossene Kurven werden um die Achse gedreht – es entsteht eine Fläche, kein Volumen.":"Åpne eller lukkede kurver roteres om aksen – resultatet er en flate, ikke et volum.",
