"Schraubstock: die Backen greifen quer zur X-Achse des Setups (an Y-min und Y-max des Rohteils); 0 = Größe und Spanntiefe passend wählen. Die Spannmittel werden einfache Körper am Ende der Zeitleiste und hier als Spannmittel eingetragen: Halter- und Kollisionsprüfung, Sicherheitsabstände und Einrichteblatt berücksichtigen sie.":"Skrustikke: bakkene griper på tvers av oppspenningens X-akse (ved Y-min og Y-max på råemnet); 0 = velg størrelse og spennedybde automatisk. Oppspenningsutstyret blir enkle kropper på slutten av tidslinjen og registreres her som oppspenningsutstyr: holder- og kollisjonskontroll, sikkerhetsavstander og oppsettark tar hensyn til dem.",
