"Schruppt simultan 4-achsig von außen nach innen: je Zustellung eine Spirale um die A-Achse (abwechselnd in +X und −X), nie tiefer als das Teil plus Aufmaß. Mit Schaft- oder Kugelfräser.":"Grovbearbeider simultan 4-akset utenfra og inn: én spiral rundt A-aksen per tilsetting (vekselvis i +X og −X), aldri dypere enn delen pluss overmål. Med sluttfres eller kulefres.",
