"Tasche auf dem Umfang aus den geschlossenen Konturen einer Skizze, die längs zur Drehachse liegt (innere Konturen bleiben als Inseln stehen). Die Skizze wird auf den Durchmesser gewickelt; ein angetriebener Schaftfräser, der zur Achse zeigt, räumt von innen nach außen (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Der Fräser taucht auf einer Rampe entlang des innersten Rings ein.":"Lomme på omkretsen fra de lukkede konturene i en skisse som ligger langs dreieaksen (indre konturer blir stående som øyer). Skissen vikles på diameteren; en drevet endefres som peker mot aksen, tømmer fra innsiden og utover (Z og C beveger seg samtidig; Fanuc: sylinderinterpolasjon G7.1). Freseren stuper ned på en rampe langs den innerste ringen.",
"Tasche gespiegelt":"Speilet lomme",
"Tasche in der Planfläche aus den geschlossenen Konturen einer Skizze (innere Konturen bleiben als Inseln stehen), mit einem angetriebenen Schaftfräser entlang Z. Geräumt wird von innen nach außen; der Fräser taucht auf einer Rampe entlang der innersten Bahn ein und bleibt innerhalb einer Ebene unten. X und C fahren gemeinsam (Fanuc: Polar-Interpolation G12.1). Tiefe ab Planfläche.":"Lomme i planflaten av de lukkede konturene i en skisse (indre konturer blir stående som øyer), med en drevet sluttfres langs Z. Utspaningen går fra innsiden og utover; fresen stikker ned på en rampe langs den innerste banen og blir nede innenfor ett nivå. X og C beveger seg sammen (Fanuc: polar interpolasjon G12.1). Dybde fra planflaten.",
