"Verrechnet zwei geschlossene Netze wirklich miteinander: innen liegende Flächen verschwinden, die Schnittkanten werden neu vernetzt. Gerechnet wird nur dort, wo sich die beiden Netze begegnen können – ein großes Netz mit einem kleinen Eingriff geht deshalb schnell. Überlappen zwei große Netze ganz, vorher „Reduzieren“.":"Beregner to lukkede nett faktisk mot hverandre: flater på innsiden forsvinner, snittkantene nettes på nytt. Det regnes bare der de to nettene kan møtes – et stort nett med et lite inngrep går derfor raskt. Overlapper to store nett helt, bruk først «Reduser».",
"Verrundung":"Avrunding",
