"Verschraubung: Scheiben und Mutter kommen mit der Schraube in einem Zug an jede angeklickte Bohrung. Die Klemmdicke ist die Länge der Bohrung – durch mehrere Teile hindurch, wenn ihre Bohrungen fluchten und aneinanderstoßen. Mit Mutter wird die kürzeste Vorzugslänge vorgeschlagen, bei der die Schraube zwei Gewindegänge aus der Mutter ragt.":"Skrueforbindelse: Skiver og mutter plasseres sammen med skruen i ett trekk ved hvert valgte hull. Klemtykkelsen er lengden på hullet – gjennom flere deler hvis hullene deres flukter og støter mot hverandre. Med mutter foreslås den korteste foretrukne lengden der skruen rager to gjengegang ut av mutteren.",
