"Wie fein Körper für STL, 3MF und den Slicer in Dreiecke zerlegt werden: Abweichung von der wahren Fläche als Anteil der Körpergröße. Netze bleiben, wie sie sind.":"Hvor fint kropper deles opp i trekanter for STL, 3MF og slicer: avvik fra den sanne flaten som andel av kroppens størrelse. Nett forblir som de er.",
"Wie fein Zylinder, Kugeln und Rundungen in der Ansicht aus Dreiecken bestehen. Feiner sieht runder aus, rechnet bei großen Modellen aber länger. Der Export hat eine eigene Einstellung (3D-Druck).":"Hvor fint sylindre, kuler og avrundinger er bygget opp av trekanter i visningen. Finere ser rundere ut, men tar lengre tid på store modeller. Eksport har sin egen innstilling (3D-utskrift).",
"Wie im System":"Som i systemet",
"Wie lange die Schneide schneiden darf, bevor sie getauscht wird. Das Fenster „Bearbeitungszeit“ rechnet daraus, wie viele Teile noch möglich sind.":"Hvor lenge skjæret kan skjære før det byttes. Vinduet «Bearbeidingstid» beregner ut fra dette hvor mange deler som fortsatt er mulig.",
