"Zahnform nach Tredgold (Ersatz-Stirnrad auf dem Rückenkegel), gerade Zähne. Das große Ende liegt in der Grundebene, die Zähne laufen zur Kegelspitze. Für Darstellung, 3D-Druck und Fräsen aus dem Vollen; geschliffene Kegelräder brauchen die Daten des Herstellers.":"Tannform etter Tredgold (ekvivalent sylindrisk tannhjul på ryggkjeglen), rette tenner. Den store enden ligger i grunnplanet, tennene løper mot kjeglespissen. For visning, 3D-printing og fresing fra helt emne; slipte koniske tannhjul trenger produsentens data.",
