"Zungen stehen am freien Ende der Lasche über und kommen in den Zuschnitt. „Schlitze als Skizze“ legt die passenden Schlitze dort an, wo die Zungen stehen – je Ebene eine Skizze, jeder Schlitz ringsum um das Spiel größer als die Zunge. In dieser Skizze den Umriss des Gegenstücks zeichnen und daraus ein Blech oder eine Extrusion machen: die Schlitze werden Ausschnitte. Das Gegenstück liegt auf den Laschenenden auf; die Zungenlänge ist üblich gleich seiner Dicke.":"Tappene stikker ut ved den frie enden av flensen og blir med i tilskjæringen. «Slisser som skisse» oppretter de passende slissene der tappene står – én skisse per plan, hver sliss er hele veien rundt større enn tappen med klaringen. Tegn omrisset av motstykket i denne skissen og lag en plate eller en ekstrudering av den: slissene blir utsnitt. Motstykket hviler på endene av flensene; tappens lengde er vanligvis lik tykkelsen på motstykket.",
