"Zwischen zwei Schnitten hebt das Werkzeug nur so weit ab, wie das Material auf dem Weg es verlangt (Rohteil abzüglich allem, was dieses Setup bis dahin gefräst hat) plus Sicherheitsabstand – und beginnt den Vorschub erst dort.{0}{1}":"Mellom to snitt løfter verktøyet seg bare så langt som materialet på veien krever (råemne minus alt denne oppspenningen har frest til da) pluss sikkerhetsavstand – og starter matingen først der.{0}{1}",
