"„Ineinander schachteln“ legt die Zuschnitte in die Lücken und Buchten ihrer Nachbarn und in deren Ausschnitte (ohne 90°-Drehen nur um 180° gewendet); der Abstand wird nie unterschritten. Ohne den Haken liegen sie nach ihrem umschließenden Rechteck in Reihen. Mit „Skizze + Körper“ entstehen flache Körper in Blechdicke, die sich in der Fertigung mit 2D-Kontur ausschneiden lassen.":"«Legg i hverandre» legger emnene i mellomrommene og buktene hos naboene og i deres utsparinger (uten 90°-dreining bare vendt 180°); avstanden underskrides aldri. Uten avmerkingen ligger de i rader etter sitt omsluttende rektangel. Med «Skisse + kropper» oppstår flate kropper i platetykkelse som kan skjæres ut i produksjonen med 2D-kontur.",
"„Innen/Außen“ braucht geschlossene Konturen – offene Kurven mit „Auf der Kurve“ fräsen":"«Innvendig/utvendig» trenger lukkede konturer – frese åpne kurver med «På kurven»",
"„Prüfen“ fährt den Ablauf in kleinen Zeitschritten ab und meldet, wann welche Körper zusammenstoßen.":"«Kontroller» kjører forløpet i små tidstrinn og melder når hvilke kropper kolliderer.",
